// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Physics C uses calculus to describe motion exactly, even when acceleration isn't constant.","blocks":[{"t":"key","text":"v(t) = dx/dt and a(t) = dv/dt. Going backward: x(t) = x₀ + ∫ v dt and v(t) = v₀ + ∫ a dt."},{"t":"p","text":"The constant-acceleration equations are special cases. When acceleration changes with time, integrate."},{"t":"ex","problem":"a(t) = 6t m/s² and v(0) = 2 m/s. Find v(t) and v(3).","steps":["v(t) = 2 + ∫₀ᵗ 6t dt = 2 + 3t²"],"answer":"v(3) = 29 m/s"},{"t":"p","text":"Displacement is the integral of velocity; distance traveled is the integral of speed |v|. On graphs, slope and area still give derivatives and integrals."}]},{"say":"In two dimensions, treat each direction separately and use vectors to combine them.","blocks":[{"t":"key","text":"Position, velocity and acceleration are vectors: r(t) = x(t)î + y(t)ĵ, v = dr/dt, a = dv/dt."},{"t":"p","text":"For projectiles, aₓ = 0 and a_y = −g. The horizontal and vertical motions are independent but share the same time."},{"t":"p","text":"Relative velocity: v_A relative to C = v_A relative to B + v_B relative to C."},{"t":"ex","problem":"A ball is launched at 20 m/s at 30° above horizontal from level ground. Find its time of flight.","steps":["v_y0 = 20 sin 30° = 10 m/s","Lands when y = 0: t = 2v_y0/g = 20/9.8"],"answer":"about 2.04 s"}]}],[{"say":"Newton's second law becomes a differential equation when forces depend on velocity. That's Physics C's specialty.","blocks":[{"t":"key","text":"ΣF = ma = m dv/dt. For systems, the center of mass accelerates according to the net external force."},{"t":"p","text":"Friction: f_k = μ_kN; static friction up to μ_sN."},{"t":"p","text":"Resistive (drag) forces like F = −bv lead to differential equations: m dv/dt = mg − bv. The object approaches terminal velocity v_T = mg/b, with v(t) = v_T(1 − e^(−bt/m))."},{"t":"ex","problem":"A 2 kg ball falls with drag F = −0.5v. What is its terminal velocity?","steps":["At terminal velocity, mg = bv","v_T = (2 × 9.8)/0.5"],"answer":"39.2 m/s"}]},{"say":"Circular motion and gravity combine in orbits. Calculus lets us handle them precisely.","blocks":[{"t":"key","text":"Centripetal acceleration a_c = v²/r = ω²r toward the center. If speed changes, there's also tangential acceleration dv/dt."},{"t":"p","text":"Universal gravitation: F = Gm₁m₂/r². Gravitational field g = GM/r². Gravitational potential energy U = −Gm₁m₂/r (zero at infinity)."},{"t":"p","text":"Orbits: for circular orbits, GMm/r² = mv²/r, so v = √(GM/r). Escape speed: v_esc = √(2GM/R). Kepler's third law: T² ∝ r³."},{"t":"ex","problem":"Why is gravitational potential energy U = −GMm/r negative?","steps":["U = −GMm/r is zero at infinity and decreases as objects get closer"],"answer":"Bound objects have negative total energy; escaping requires raising total energy to zero"}]}],[{"say":"With calculus, work is an integral, and force is the negative slope of potential energy.","blocks":[{"t":"key","text":"W = ∫ F · dx. For a spring, W = ∫ kx dx = ½kx². The work–energy theorem: W_net = ΔK."},{"t":"p","text":"For conservative forces, F = −dU/dx. Equilibrium points occur where dU/dx = 0: stable at minima of U, unstable at maxima."},{"t":"ex","problem":"F(x) = 3x² N acts from x = 0 to 2 m. Find the work done.","steps":["W = ∫₀² 3x² dx = x³ from 0 to 2"],"answer":"8 J"},{"t":"p","text":"Conservative forces (gravity, springs) have path-independent work; nonconservative forces (friction) dissipate mechanical energy."}]},{"say":"Energy conservation solves problems that would be messy with forces alone.","blocks":[{"t":"key","text":"K₁ + U₁ + W_other = K₂ + U₂. With only conservative forces, mechanical energy is constant."},{"t":"p","text":"Power P = dW/dt = F · v. Average power = W/Δt."},{"t":"ex","problem":"A 1,500 kg car moves at 20 m/s against a total resistive force of 600 N. What power must the engine supply to keep speed constant?","steps":["At constant speed, engine force = 600 N","P = Fv = 600 × 20"],"answer":"12,000 W (12 kW)"},{"t":"p","text":"Energy diagrams (U vs. x with a total energy line) show turning points where K = 0 and regions where motion is allowed."}]}],[{"say":"Momentum and impulse handle collisions and changing forces with ease.","blocks":[{"t":"key","text":"p = mv. Impulse J = ∫ F dt = Δp. ΣF = dp/dt."},{"t":"p","text":"On a force–time graph, the area under the curve is the impulse."},{"t":"ex","problem":"A force F(t) = 10t N acts on a 2 kg object from t = 0 to 3 s. Find the change in velocity.","steps":["J = ∫₀³ 10t dt = 5t² from 0 to 3 = 45 N·s"],"answer":"Δv = 45/2 = 22.5 m/s"},{"t":"p","text":"Center of mass: x_cm = Σmᵢxᵢ/Σmᵢ, or ∫x dm / M for continuous objects. If no net external force acts, the center of mass moves at constant velocity."}]},{"say":"In collisions, momentum is always conserved. Kinetic energy depends on the type of collision.","blocks":[{"t":"key","text":"Isolated system: Σp_before = Σp_after. Elastic collisions also conserve kinetic energy; inelastic do not. Perfectly inelastic collisions end with the objects stuck together."},{"t":"p","text":"For a 1D elastic collision between equal masses where one is at rest, they exchange velocities."},{"t":"p","text":"In 2D, conserve momentum separately in the x and y directions."},{"t":"ex","problem":"A 3 kg cart at 4 m/s sticks to a 1 kg cart at rest. Find the final speed and kinetic energy lost.","steps":["12 = 4v, so v = 3 m/s","K before = 24 J; K after = ½(4)(9) = 18 J"],"answer":"v = 3 m/s; 6 J lost"}]}],[{"say":"Rotation has its own versions of position, velocity and mass. Calculus computes rotational inertia for any shape.","blocks":[{"t":"key","text":"ω = dθ/dt, α = dω/dt. Linking to linear: v = rω, a_t = rα. Moment of inertia I = Σmr² = ∫r² dm."},{"t":"p","text":"Common results: thin rod about its center ML²/12, about one end ML²/3; solid disk ½MR²; hoop MR²; solid sphere (2/5)MR²."},{"t":"p","text":"Parallel axis theorem: I = I_cm + Md²."},{"t":"ex","problem":"Use the parallel axis theorem to find I for a rod about its end from I_cm = ML²/12.","steps":["d = L/2","ML²/12 + M(L/2)² = ML²/12 + 3ML²/12"],"answer":"ML²/3"}]},{"say":"Torque causes angular acceleration, just as force causes linear acceleration.","blocks":[{"t":"key","text":"τ = r × F, with magnitude rF sin θ. Στ = Iα. For static equilibrium: ΣF = 0 and Στ = 0 about any point."},{"t":"p","text":"Systems with ropes over pulleys with mass combine translational and rotational equations, linked by a = rα."},{"t":"ex","problem":"A 2 kg disk (R = 0.5 m) has a string wrapped around it pulled with 4 N. Find α.","steps":["I = ½(2)(0.5²) = 0.25 kg·m²","τ = 4 × 0.5 = 2 N·m"],"answer":"α = 2/0.25 = 8 rad/s²"},{"t":"tip","text":"For equilibrium problems, choose a pivot point where unknown forces act, so their torques are zero."}]}],[{"say":"Rotating objects store energy, and rolling objects have both translational and rotational energy.","blocks":[{"t":"key","text":"K_rot = ½Iω². Rolling without slipping: v_cm = Rω, K = ½Mv² + ½Iω². Work by torque: W = ∫τ dθ. Power: P = τω."},{"t":"ex","problem":"A solid sphere rolls without slipping down a ramp of height h. Find its speed at the bottom.","steps":["Mgh = ½Mv² + ½(2/5)MR²(v/R)² = (7/10)Mv²"],"answer":"v = √(10gh/7)"},{"t":"p","text":"Objects with smaller I/(MR²) roll faster down ramps: sphere beats disk beats hoop."},{"t":"oops","text":"Don't forget the rotational term. A rolling ball moves slower at the bottom of a ramp than a sliding block, because some energy goes into spinning."}]},{"say":"Angular momentum is conserved when no external torque acts, from spinning skaters to collapsing stars.","blocks":[{"t":"key","text":"L = Iω for rigid bodies; for a particle, L = r × p. Στ = dL/dt. If net external torque is zero, L is conserved."},{"t":"ex","problem":"A 0.5 kg ball moving at 4 m/s sticks to the end of a 1 m rod (I = 0.2 kg·m²) pivoted at the other end. Find ω afterward.","steps":["Before: L = mvr = 0.5 × 4 × 1 = 2 kg·m²/s","After: I_total = 0.2 + 0.5(1²) = 0.7"],"answer":"ω = 2/0.7 ≈ 2.86 rad/s"},{"t":"p","text":"Angular momentum is conserved in rotational collisions, but kinetic energy usually is not."}]}],[{"say":"Simple harmonic motion is described by a differential equation whose solutions are sines and cosines.","blocks":[{"t":"key","text":"SHM occurs when F = −kx, giving d²x/dt² = −(k/m)x. Solution: x(t) = A cos(ωt + φ) with ω = √(k/m)."},{"t":"p","text":"Period: mass-spring T = 2π√(m/k); simple pendulum T = 2π√(L/g) (small angles); physical pendulum T = 2π√(I/(mgd))."},{"t":"ex","problem":"Show that x(t) = A cos(ωt) satisfies the SHM equation.","steps":["d²x/dt² = −Aω² cos(ωt) = −ω²x"],"answer":"It works when ω² = k/m"},{"t":"p","text":"Velocity and acceleration: v_max = Aω at equilibrium; a_max = Aω² at the turning points."}]},{"say":"Energy sloshes between kinetic and potential in an oscillator, while the total stays fixed.","blocks":[{"t":"key","text":"E = ½kA² = ½mv² + ½kx². So v = ω√(A² − x²)."},{"t":"ex","problem":"A 0.25 kg mass on a spring (k = 100 N/m) oscillates with A = 0.2 m. Find its speed at x = 0.1 m.","steps":["ω = √(100/0.25) = 20 rad/s","v = 20√(0.04 − 0.01) = 20√0.03"],"answer":"about 3.46 m/s"},{"t":"p","text":"Damping removes energy, decreasing amplitude over time. Driving an oscillator at its natural frequency causes resonance, with large amplitudes."}]}]];
export default text;
